import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

class LongestPalindromicSubstringTest {
    private LongestPalindromicSubstring obj = new LongestPalindromicSubstring();
    @Test
    void longestPalindromeTest(){
        Assertions.assertEquals(obj.longestPalindrome("babad").length(), 3);
        Assertions.assertEquals(obj.longestPalindrome("cbbd").length(), 2);
        Assertions.assertEquals(obj.longestPalindrome("a").length(), 1);
        Assertions.assertEquals(obj.longestPalindrome("ac").length(), 1);
        Assertions.assertEquals(obj.longestPalindrome("aacabdkacaa").length(), 3);
        Assertions.assertEquals(obj.longestPalindrome("").length(), 5);
        Assertions.assertEquals(obj.longestPalindrome("").length(), 500);
    }
}